const AGENT_ID = 99811284;
const body = $('CU Webhook').first().json.body || {};
const taskId = body.task_id;
const items = (body.history_items || []).filter(h => h && h.field === 'comment' && h.comment);
const h = items[items.length - 1];
let matched = false, reviewer_user_id = '', caller_username = '';
let triggering_comment_id = '', reply_to_comment_id = '', triggering_comment_text = '';
if (h) {
  const ops = h.comment.comment || [];
  const tagged = ops.some(b => b && b.type === 'tag' && b.user && Number(b.user.id) === AGENT_ID);
  const author = h.comment.user || h.user || {};
  if (tagged) {
    matched = true;
    reviewer_user_id = String(author.id || '');
    caller_username = author.username || '';
  }
  triggering_comment_id = String(h.comment.id || h.id || '');
  // ClickUp threads are single-level: POSTing /comment/{id}/reply to a comment that is ITSELF a reply
  // returns 'Unsupported Entity' -> fallback would post a NEW top-level comment (answer lands in a new thread).
  // For a reply, h.comment.parent is the top-level (repliable) comment id; for a top-level comment it is the task id.
  // Reply to the thread ROOT to stay in the caller's thread. Keep triggering_comment_id (own id) as the dedup key.
  const parent = String(h.comment.parent || '');
  reply_to_comment_id = (parent && parent !== String(taskId)) ? parent : triggering_comment_id;
  triggering_comment_text = h.comment.text_content
    || ops.filter(op => op && op.type !== 'tag').map(op => op.text || '').join('')
    || '';
}
return [{ json: { matched, taskId, reviewer_user_id, caller_username, triggering_comment_id, reply_to_comment_id, triggering_comment_text } }];

const d = $('Detect Mention').first().json;
const taskId = d.taskId;
const ownCommentId = String(d.triggering_comment_id || '');   // dedup key (own comment id)
const replyTargetId = String(d.reply_to_comment_id || '');     // spine reply target (thread root)
const reviewerId = String(d.reviewer_user_id || '');

// Resolve impact from the task's [AI] Wplyw custom field (same field id + option map as Assemble Parent Context).
const IMPORTANCE_FIELD_ID = '55c7ff79-1857-41e6-87b4-bd46678e1470';
const FALLBACK = {
  '4c440e3f-94e8-4239-b9ec-54051090e2a4': 'Niski',
  '1947d7f8-b394-4d7f-b555-9b2ad62fe38e': 'Średni',
  '8c96537f-8bf8-405f-8a1c-c4fb39d80691': 'Wysoki',
  '7780679d-6e30-466f-afae-d7728a31cbde': 'Krytycznie ważne'
};
const VALID = ['Niski', 'Średni', 'Wysoki', 'Krytycznie ważne'];
let impact = '';
try {
  const task = $('Fetch Task Impact').first().json || {};
  const cf = (task.custom_fields || []).find(f => f.id === IMPORTANCE_FIELD_ID);
  const v = cf ? cf.value : undefined;
  if (v !== undefined && v !== null && v !== '') {
    const opts = (cf.type_config && cf.type_config.options) || [];
    const m = opts.find(o => o.id === v) || opts.find(o => String(o.orderindex) === String(v));
    impact = m ? m.name : (FALLBACK[v] || '');
  }
} catch (e) {}
if (VALID.indexOf(impact) === -1) impact = 'Średni';   // default: absent / 'n/d' / unreadable

// Job contract (ADR-056 Block 2). Top-level invocation_type = queue vocabulary 'explicit_mention'
// (drives priority + jobId + agent_runs.triggered_by idempotency). payload carries the spine-context
// fields the consumer maps to the ingress; the consumer derives the spine-vocabulary invocation_type.
return [{ json: {
  task_id: taskId,
  caller_user_id: reviewerId,
  impact: impact,
  invocation_type: 'explicit_mention',
  enqueued_at: new Date().toISOString(),
  payload: {
    reviewer_user_id: reviewerId,
    caller_username: d.caller_username || '',
    triggered_by: 'explicit_mention',
    triggering_comment_id: replyTargetId,
    triggering_comment_text: d.triggering_comment_text || '',
    dedup_comment_id: ownCommentId
  }
} }];
